function UIBattleEndTrialInfo:SetTrialScore()
    local showData = BattleEndMgr.showData
    if IsNull(showData) or (not isSet(showData, "response")) or (not isSet(showData.response, "score")) then return end
    self.TxtScore.text = checkInt(showData.response.score)
    local trailBattleMgr = import('Game.TrailBattle.TrailBattleMgr'):GetInstance()
    local enterData = trailBattleMgr:GetEnterData()
    self.TxtScoreHistory.text = enterData.score
    local isNew = checkInt(showData.response.score) > checkNumber(enterData.score)
    KTool.SetActive(self.ImgUP, isNew)
end

return UIBattleEndTrialInfo